mkdir -p /tmp/sms-gate-check && cat > /tmp/sms-gate-check/check.mjs <<'EOF'
import { checkSms } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/knock-inv-g1-3/bot.mjs';
import assert from 'node:assert/strict';

const ok = { phone: '+13125550142', timeZone: 'America/Chicago', marketingConsent: true, optedOutAt: null };
const mk = (kind, body, to = {}) => ({ kind, body, to: { ...ok, ...to } });
// 2025-03-10 15:00 UTC = 10:00 Chicago (CDT started Mar 9, 2025)
const noonChicago = new Date('2025-03-10T15:00:00Z');
const MKT = 'Sale today! Reply STOP to opt out.';
const TX = 'Your login code is 445892.';

const cases = [
  ['tx allowed at any hour', mk('transactional', TX), new Date('2025-03-10T03:00:00Z'), { allowed: true, reason: null }],
  ['mkt allowed in window', mk('marketing', MKT), noonChicago, { allowed: true, reason: null }],
  ['mkt no consent', mk('marketing', MKT, { marketingConsent: false }), noonChicago, { allowed: false, reason: 'no_marketing_consent' }],
  ['mkt opted out', mk('marketing', MKT, { optedOutAt: '2025-03-01T00:00:00Z' }), noonChicago, { allowed: false, reason: 'opted_out' }],
  ['mkt missing STOP', mk('marketing', 'Sale today!'), noonChicago, { allowed: false, reason: 'missing_opt_out_language' }],
  ['mkt before 8am local', mk('marketing', MKT), new Date('2025-03-10T13:30:00Z'), { allowed: false, reason: 'quiet_hours' }], // 08:30? -> 13:30Z = 08:30 CDT? no: check below
  ['mkt 7:59 local', mk('marketing', MKT), new Date('2025-03-10T12:59:00Z'), { allowed: false, reason: 'quiet_hours' }],
  ['mkt 8:00 local', mk('marketing', MKT), new Date('2025-03-10T13:00:00Z'), { allowed: true, reason: null }],
  ['mkt 20:59 local', mk('marketing', MKT), new Date('2025-03-11T01:59:00Z'), { allowed: true, reason: null }],
  ['mkt 21:00 local', mk('marketing', MKT), new Date('2025-03-11T02:00:00Z'), { allowed: false, reason: 'quiet_hours' }],
  ['promo labeled transactional', mk('transactional', '20% off your next order'), noonChicago, { allowed: false, reason: 'promotional_content_labeled_transactional' }],
  ['unknown kind', mk('promo', MKT), noonChicago, { allowed: false, reason: 'unknown_kind' }],
  ['empty body', mk('marketing', '   '), noonChicago, { allowed: false, reason: 'empty_body' }],
  ['non-US phone', mk('transactional', TX, { phone: '+442071838750' }), noonChicago, { allowed: false, reason: 'invalid_phone_number' }],
  ['bad tz', mk('marketing', MKT, { timeZone: 'Mars/Olympus' }), noonChicago, { allowed: false, reason: 'invalid_time_zone' }],
  ['future opt-out', mk('marketing', MKT, { optedOutAt: '2030-01-01T00:00:00Z' }), noonChicago, { allowed: false, reason: 'invalid_opt_out_timestamp' }],
  ['bad now', mk('marketing', MKT), 'nope', { allowed: false, reason: 'invalid_now' }],
  ['no message', null, noonChicago, { allowed: false, reason: 'invalid_message' }],
];
for (const [name, msg, now, want] of cases) {
  const got = checkSms(msg, now);
  try { assert.deepEqual(got, want); console.log('PASS', name, JSON.stringify(got)); }
  catch (e) { console.log('FAIL', name, 'got', JSON.stringify(got), 'want', JSON.stringify(want)); process.exitCode = 1; }
}

// Server time zone must not matter: same instant, different TZ env, same answer.
const edge = mk('marketing', MKT); // 12:59Z = 07:59 CDT -> blocked
for (const tz of ['UTC', 'Asia/Tokyo', 'America/Los_Angeles']) {
  const r = await import('node:child_process').then(cp => cp.execFileSync(process.execPath, ['--input-type=module', '-e',
    `import {checkSms} from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/knock-inv-g1-3/bot.mjs';
     console.log(JSON.stringify(checkSms(${JSON.stringify(edge)}, new Date('2025-03-10T12:59:00Z'))))`], { env: { ...process.env, TZ: tz } }).toString().trim());
  console.log('TZ', tz, r);
  assert.equal(JSON.parse(r).reason, 'quiet_hours');
}
console.log('done');
EOF
